target='AlgebraicJacobian.Challenge'
# BFS from seeds recording parent
seeds=['AlgebraicJacobian.Picard.Pic0ChartCoveragePointwise','AlgebraicJacobian.Picard.Pic0ChartCoverageNoDrop']
for seed in seeds:
    par={seed:None}
    q=collections.deque([seed])
    found=None
    while q:
        m=q.popleft()
        if m==target: found=m; break
        for c in imports.get(m,[]):
            if c not in par and c in imports:
                par[c]=m; q.append(c)
    if found:
        path=[]
        cur=target
        while cur: path.append(cur); cur=par[cur]
        print(seed,"->")
        for p in reversed(path): print("   ",p)
    else:
        print(seed,": Challenge NOT reachable")
